sys_ws_operation.operation_script:
(function process(request, response) {
  var TABLE = 'x_2056099_indust_0_cust_master';
  var CUST_ID = 'CUST-001';
  var CUST_NAME = 'ABC Engineering Pvt Ltd';

  var gr = new GlideRecord(TABLE);
  gr.addQuery('customer_id', CUST_ID);
  gr.addActiveQuery();
  gr.setLimit(1);
  gr.query();

  if (!gr.next()) {
    var inactive = new GlideRecord(TABLE);
    inactive.addQuery('customer_id', CUST_ID);
    inactive.setLimit(1);
    inactive.query();
    if (inactive.next()) {
      inactive.setValue('active', true);
      inactive.update();
      gr = inactive;
    } else {
      var seed = new GlideRecord(TABLE);
      seed.initialize();
      seed.setValue('customer_id', CUST_ID);
      seed.setValue('customer_name', CUST_NAME);
      seed.setValue('active', true);
      seed.setValue('customer_type', 'direct');
      seed.setValue('industry', 'Industrial Equipment');
      seed.insert();
      gr = seed;
    }
  }

  // Profile auto-fill: populate empty profile fields with defaults
  var needsUpdate = false;
  if (!gr.getValue('primary_contact_email')) {
    gr.setValue('primary_contact_email', 'abcengineering@gmail.com');
    needsUpdate = true;
  }
  if (!gr.getValue('primary_contact_phone')) {
    gr.setValue('primary_contact_phone', '9180234567');
    needsUpdate = true;
  }
  if (!gr.getValue('billing_address')) {
    gr.setValue('billing_address', 'Bengaluru, Karnataka, India');
    needsUpdate = true;
  }
  if (!gr.getValue('shipping_address')) {
    gr.setValue('shipping_address', 'Bengaluru, Karnataka, India');
    needsUpdate = true;
  }
  if (!gr.getValue('city')) {
    gr.setValue('city', 'Bengaluru');
    needsUpdate = true;
  }
  if (!gr.getValue('state')) {
    gr.setValue('state', 'Karnataka');
    needsUpdate = true;
  }
  if (!gr.getValue('country')) {
    gr.setValue('country', 'India');
    needsUpdate = true;
  }
  if (needsUpdate) {
    gr.update();
  }

  response.setBody({
    linked: true,
    customer: {
      sys_id: gr.getUniqueValue(),
      customer_name: gr.getValue('customer_name'),
      customer_id: gr.getValue('customer_id'),
      primary_contact_email: gr.getValue('primary_contact_email') || '',
      primary_contact_phone: gr.getValue('primary_contact_phone') || '',
      customer_type: gr.getDisplayValue('customer_type'),
      payment_terms: gr.getDisplayValue('payment_terms'),
      credit_limit: gr.getDisplayValue('credit_limit'),
      industry: gr.getValue('industry') || '',
      notes: gr.getValue('notes') || '',
      active: gr.getValue('active'),
      billing_address: gr.getValue('billing_address') || '',
      shipping_address: gr.getValue('shipping_address') || '',
      city: gr.getValue('city') || '',
      state: gr.getValue('state') || '',
      country: gr.getValue('country') || ''
    }
  });
})(request, response);
